  [Notes]
  <bass>,<tenor>,<alto>,<soprano>,<triad root>:<triad type>
  <bass>,<tenor>,<alto>,<soprano>,<triad root>:<triad type>
  <bass>,<tenor>,<alto>,<soprano>,<triad root>:<triad type>
