	def __str__(self):
		return self.func+"("+",".join(map(str,self.argnames))+")="+str(self.expansion)

	def eval(self,symtab):
		raise "Evaluating a defined function"

	def evalFunction(self,symtab,args):
		newsymtab=symtab.copy()
