class NetWorldModel:

  def __init__ (self):
    self.left = 0
    self.bottom = 0
    self.right = 400
    self.top = 400
    self.nodes = {}
    self.ips = {}
    self.events = []
    self.currentEvent = -1

  def __del (self):
    self.Clear ()

  def Clear (self):
     self.nodes.clear()
     self.ips.clear()

  def SetArenaBounds(self, x1, x2, y1, y2):
    if x1 <= x2:
      self.left = x1
      self.right = x2
    else:
      self.left = x2
      self.right = x1

    if y1 <= y2:
      self.bottom = y1
      self.top = y2
    else:
      self.bottom = y2
      self.top = y1

    ns3.logging.debug ("bounds %d, %d --- %d, %d" % \
                       (self.left, self.bottom, self.right, self.top))

  def PushEvent (self, event):
    self.events.append(event)

  def Start (self):
    self.Clear()
    self.currentEvent = 0

  def End (self):
    return self.currentEvent >= len (self.events)

  def ProcessUpTo (self, timestamp):
    #ns3.logging.debug("Bound %d" % timestamp)
    while not self.End() and self.events[self.currentEvent].timestamp <= timestamp:
      self.events[self.currentEvent].Process (self)
      self.currentEvent += 1

  def GetLastTimestamp (self):
    if len (self.events) <= 0:
      return 0
    else:
      return self.events[len (self.events) - 1].timestamp

  def GetNode (self, id):
    if id not in self.nodes:
      node = NetWorldNode(id)
      self.nodes[id] = node
      return node
    else:
      return self.nodes [id]

  def GetNodeByIP (self, ip):
    if ip in self.ips:
      return self.ips [ip]
    else:
      return None

  def MapIP (self, ip, nodeId):
    ns3.logging.debug ("Map %s -> %d" % (ip, nodeId))
    node = self.GetNode(nodeId)
