def parse_value(text):
	low = text.lower()
	if low in ["true", "yes", "on"]:
		return True
	elif low in ["false", "no", "off"]:
		return False
	else:
		try:
			return float(text)
		except ValueError:
			return text
		except OverflowError:
			return text

